begin;
set local statement_timeout='20s';
do $tests$
declare c uuid:=gen_random_uuid();other_c uuid:=gen_random_uuid();u uuid:=gen_random_uuid();other_u uuid:=gen_random_uuid();viewer uuid:=gen_random_uuid();ctx jsonb;req jsonb;result jsonb;before_secret uuid;denied boolean;rid uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(u,'access-'||u||'@example.invalid'),(other_u,'access-'||other_u||'@example.invalid'),(viewer,'access-'||viewer||'@example.invalid');
 insert into public.user_profiles(user_id,display_name) values(u,'Synthetic admin');
 insert into public.clubs(id,name,slug,created_by) values(c,'First test club','access-'||c,u),(other_c,'Other test club','access-'||other_c,other_u);
 insert into public.club_memberships(club_id,user_id,role,permission_role,involvement) values(c,u,'admin','admin','player'),(other_c,other_u,'admin','admin','player'),(c,viewer,'player','none','player');
 insert into club_selection_private.access(club_id,mode,status,head_selector_id) values(c,'standalone','active',viewer),(other_c,'standalone','active',other_u);
 perform set_config('request.jwt.claim.sub',u::text,true);
 ctx:=public.playhq_onboarding(c);assert ctx->>'state'='not_requested' and ctx->>'revision'='0';
 assert ctx#>>'{request,contact_name}'='Synthetic admin','Contact defaults to the current admin';
 req:=jsonb_build_object('revision',0,'request',jsonb_build_object('association','Example Association','club_url','https://www.playhq.com/cricket-australia/org/example/123','contact_name','Club contact','contact_email','club@example.invalid','contact_role','Secretary'));
 ctx:=public.playhq_onboarding(c,'save_request',req);assert ctx->>'revision'='1' and ctx->>'requested_at' is null,'Preparing never submits';
 denied:=false;begin perform public.playhq_onboarding(c,'save_request',req);exception when raise_exception then denied:=true;end;assert denied,'Stale edits rejected';
 denied:=false;begin perform public.playhq_onboarding(c,'mark_requested','{"revision":1}');exception when raise_exception then denied:=true;end;assert denied,'Confirmation is required';
 ctx:=public.playhq_onboarding(c,'mark_requested','{"revision":1,"authorised":true}');assert ctx->>'state'='awaiting_key';assert ctx=public.playhq_onboarding(c,'mark_requested','{"revision":1,"authorised":true}'),'Repeat sent confirmation is idempotent';
 assert not exists(select 1 from club_selection_private.playhq_connections where club_id=c),'Requesting does not create a connection';
 perform set_config('request.jwt.claim.sub',viewer::text,true);denied:=false;begin perform public.playhq_onboarding(c);exception when insufficient_privilege then denied:=true;end;assert denied,'Selectors cannot read connection or contact details';
 perform set_config('request.jwt.claim.sub',other_u::text,true);denied:=false;begin perform public.playhq_onboarding(c);exception when insufficient_privilege then denied:=true;end;assert denied,'Other clubs cannot read request details';
 assert public.playhq_onboarding(other_c)->>'state'='not_requested','The second club has independent status';
 perform set_config('request.jwt.claim.sub','',true);denied:=false;begin perform public.playhq_onboarding(c);exception when insufficient_privilege then denied:=true;end;assert denied,'Anonymous callers rejected';
 perform set_config('request.jwt.claim.sub',u::text,true);
 req:=jsonb_build_object('request_id',rid,'connection_version',null,'organisation_id',gen_random_uuid(),'association_id',gen_random_uuid(),'api_key','synthetic-test-key-not-real','authorised',false);
 denied:=false;begin perform public.playhq_onboarding(c,'configure',req);exception when raise_exception then denied:=true;end;assert denied,'Club credential attestation required';
 req:=jsonb_set(req,'{authorised}','true');ctx:=public.playhq_onboarding(c,'configure',req);assert ctx->>'state'='needs_check' and not (ctx->>'verified')::boolean,'Saving does not claim verification';
 select secret_id into before_secret from club_selection_private.playhq_connections where club_id=c;
 result:=public.playhq_onboarding(c,'configure',req);assert result=ctx and (select secret_id=before_secret from club_selection_private.playhq_connections where club_id=c),'Retry reuses the existing Vault secret';
 assert not (select q.payload::text||q.result::text from club_selection_private.requests q where q.club_id=c and q.request_id=rid) like '%synthetic-test-key%','Receipt never stores the key';
 assert ctx::text not like '%synthetic-test-key%' and not ctx?'secret_id','Context never returns credentials';
 denied:=false;begin perform public.playhq_onboarding(c,'configure',jsonb_set(req,'{request_id}',to_jsonb(gen_random_uuid())));exception when raise_exception then denied:=true;end;assert denied,'Stale replacement rejected';
 update club_selection_private.playhq_connections set verified_at=now(),polling_enabled=true where club_id=c;
 assert public.playhq_onboarding(c)->>'state'='connected','Only verified provider access shows connected';
 req:=jsonb_set(jsonb_set(req,'{request_id}',to_jsonb(gen_random_uuid())),'{connection_version}',ctx->'connection_version');ctx:=public.playhq_onboarding(c,'configure',req);
 assert ctx->>'state'='needs_check' and not (ctx->>'polling_enabled')::boolean,'Replacing credentials resets verification and pauses checks';
 assert not exists(select 1 from vault.secrets where id=before_secret),'Replaced secret removed';
 assert (select count(*)=1 from club_selection_private.playhq_access_requests where club_id in(c,other_c)),'No other-club changes';
 assert not has_table_privilege('authenticated','club_selection_private.playhq_access_requests','SELECT'),'Private request table inaccessible directly';
 assert not has_function_privilege('anon','public.playhq_onboarding(uuid,text,jsonb)','EXECUTE'),'Anonymous RPC grant absent';
 assert not has_function_privilege('service_role','public.playhq_onboarding(uuid,text,jsonb)','EXECUTE'),'Service callers cannot impersonate a club administrator';
end $tests$;
rollback;
select 'Club separation, admin permissions, explicit sent status, stale edits, Vault reuse and credential replacement passed.' result;
